/* ---- GRAFICA DI PROVA: casse, barili e matassa di corda d'arte ---- */
GfxNew.props=function(){
  const D={"cassa_c": "", "cassa_a": "", "barile_a": "", "barile_b": "", "corda": ""},M={"cassa_c": [56.3, 47.3, 28.0, 46.7], "cassa_a": [58.4, 63.0, 30.1, 62.2], "barile_a": [34.1, 40.8, 17.1, 40.1], "barile_b": [34.0, 40.8, 17.0, 40.1], "corda": [36.0, 31.5, 16.3, 26.5]};
  const mkA=(k,sink,shk)=>{const m=M[k],lw=m[0],lh=m[1],img=new Image(),[c,x]=mk(lw,lh),s={c,w:lw,h:lh,ax:m[2],ay:m[3],art:1,sink:sink,shk:shk||1};
    img.onload=()=>{x.clearRect(0,0,lw,lh);x.drawImage(img,0,0,lw,lh);
      const ao=x.createLinearGradient(0,lh*.82,0,lh);ao.addColorStop(0,'rgba(30,18,6,0)');ao.addColorStop(1,'rgba(30,18,6,.3)');x.globalCompositeOperation='source-atop';x.fillStyle=ao;x.fillRect(0,0,lw,lh);x.globalCompositeOperation='source-over';
      const[c2,x2]=mk(lw,lh);x2.drawImage(c,0,0,lw,lh);x2.globalCompositeOperation='source-in';x2.fillStyle='#0e1c0a';x2.fillRect(0,0,lw,lh);s.sh=c2;s.ok=1};
    img.src='data:image/webp;base64,'+D[k];return s};
  SP.crate=mkA('cassa_c',-3,.55);SP.crateO=mkA('cassa_a',-3,.55);
  SP.barrel=[mkA('barile_a',-2,.5),mkA('barile_b',-2,.5)];
  SP.coil=mkA('corda',-2,.3);
};
